  put(Q.multiple("ped-004", "ped-main", "c6", "k1", "高等教育的基本特征包括（　　）", ["专业性", "学术性", "终结性", "开放性"], ["A", "B", "D"], 3, "高等教育以专业教育为组织形式，具有学术性与开放性；它是终身教育体系中的一环，并不具有\"终结性\"。"), "");
  put(Q.judge("ped-005", "ped-main", "c0", "k1", "高等教育就是大学教育。", true, 1, "高等教育还包括学院、高等专科学校、职业技术学院、成人高等学校等，大学只是实施高等教育的机构之一。"), "");
