  put(Q.single("ped-007", "ped-main", "c5", "k1", "确立高等教育目的的根本依据是（　　）", ["政府的政策文件", "社会需要与人的发展需要的统一", "学校的办学传统", "市场的就业需求"], "B", 2, "高等教育目的既要反映社会发展的需要，也要反映受教育者个体发展的需要，二者统一才是根本依据；政策、传统、就业只是影响因素。"), "");
  put(Q.single("ped-008", "ped-main", "c14", "k2", "高等教育最基本、最古老的职能是（　　）", ["培养人才", "发展科学", "服务社会", "文化传承创新"], "A", 2, "人才培养是高等学校的第一职能，也是大学诞生之初就承担的功能；科学研究于 19 世纪洪堡大学改革后成为第二职能，社会服务则是 20 世纪才系统化的第三职能。"), "");
  put(Q.multiple("ped-009", "ped-main", "c14", "k2", "高等教育的功能包括（　　）", ["个体发展功能", "社会功能", "文化传承创新功能", "替代基础教育的功能"], ["A", "B", "C"], 3, "高等教育具有促进个体发展、推动社会进步、传承创新文化等功能；它建立在基础教育之上，不能替代基础教育。"), "");
  put(Q.judge("ped-010", "ped-main", "c13", "k1", "高等教育目的具有导向、激励和评价功能。", true, 1, "教育目的是教育工作的出发点和归宿，对教育活动起导向作用，对师生起激励作用，也是检验教育效果的评价标准。"), "");
  put(Q.short("ped-011", "ped-main", "c2", "k1", "简述高等教育目的的基本内涵及其确立依据。", "高等教育目的是指一定社会对高等教育所要培养的人的总要求，规定培养人才的质量规格与基本方向。其内涵包括：培养德智体美劳全面发展的高级专门人才；坚持立德树人，把思想政治教育贯穿全过程；兼顾社会需要与个体发展。确立依据主要有两方面：一是社会依据，即生产力发展水平、社会制度与文化传统对人才规格的客观要求；二是个体依据，即受教育者身心发展规律与个性发展需要。二者必须统一，任何片面强调其一的做法都会导致教育目的的偏差。", [["培养规格", "质量规格"], "总要求", "德智体美劳", "依据"], 10, "答题抓\"内涵 + 两大依据 + 二者统一\"三层，采分点写全即可。"), "");
  put(Q.blank("ped-012", "ped-main", "c6", "k2", "人才培养、科学研究、社会服务被视为高等学校的三大____。", ["职能", "功能"], 2, "三大职能说由纽曼、洪堡、威斯康星思想逐步发展而来，文化传承创新常被称为第四职能。"), "");
  put(Q.single("ped-013", "ped-main", "c5", "k1", "我国高等教育管理体制改革后实行（　　）", ["中央统一管理", "中央和省级人民政府两级管理、以省级人民政府管理为主", "高校完全自治", "行业部门管理为主"], "B", 2, "《高等教育法》确立了两级管理、以省级政府统筹为主的体制，扩大了地方和高校的办学自主权。"), "");
  put(Q.single("ped-014", "ped-main", "c5", "k1", "我国设立高等学校实行的基本制度是（　　）", ["备案制", "审批制", "登记制", "核准制"], "B", 2, "《高等教育法》规定，设立高等学校由国务院教育行政部门审批；设立实施专科教育的高等学校，经国务院授权也可由省级人民政府审批。"), "");
