  put(Q.single("ped-020", "ped-main", "c9", "k1", "按课程呈现方式划分，高校课程可分为（　　）", ["必修课与选修课", "显性课程与隐性课程", "通识课与专业课", "理论课与实践课"], "B", 2, "按呈现方式分为显性课程（列入教学计划、有明确目标）与隐性课程（校园文化、师生交往中潜移默化的影响）。"), "");
  put(Q.single("ped-021", "ped-main", "c10", "k2", "以真实案例引导学生分析讨论、提高决策能力的教学方法是（　　）", ["讲授法", "案例教学法", "演示法", "练习法"], "B", 2, "案例教学法源于哈佛法学院，通过真实情境的分析讨论训练学生的问题判断与决策能力，在高校专业教育中应用广泛。"), "");
  put(Q.single("ped-022", "ped-main", "c13", "k2", "在教学过程中为了解学习进展、及时调整教学而进行的评价是（　　）", ["诊断性评价", "形成性评价", "终结性评价", "相对性评价"], "B", 2, "形成性评价发生在教学过程中，目的是反馈与改进；诊断性评价在教學前进行，终结性评价在教学结束后进行。"), "");
  put(Q.multiple("ped-023", "ped-main", "c8", "k1", "高等学校教学应遵循的基本原则包括（　　）", ["科学性与思想性统一", "理论联系实际", "因材施教", "以教师为中心"], ["A", "B", "C"], 3, "A、B、C 三项均为高校教学的基本原则；D 项“以教师为中心”不是教学原则，现代教学强调教师主导与学生主体相结合。"), "");
  put(Q.multiple("ped-024", "ped-main", "c10", "k1", "高等学校常用的教学方法有（　　）", ["讲授法", "讨论法", "案例教学法", "注入式教学"], ["A", "B", "C"], 3, "高校教学方法以启发式为核心，讲授、讨论、案例、探究、项目式等常结合使用。"), "");
  put(Q.judge("ped-025", "ped-main", "c9", "k1", "隐性课程不属于高校课程体系的组成部分。", true, 1, "隐性课程虽不列入教学计划，但通过校园文化、制度环境、师生交往对学生产生持久影响，是课程体系的重要组成部分。"), "");
