  put(Q.multiple("ped-031", "ped-main", "c8", "k1", "高等学校科学研究的基本类型包括（　　）", ["基础研究", "应用研究", "开发研究", "教学研究"], ["A", "B", "C"], 3, "按研究性质通常分为基础研究、应用研究和开发研究（试验发展）；教学研究属于教育研究范畴，不属于科研类型的标准划分。"), "");
  put(Q.judge("ped-032", "ped-main", "c8", "k1", "高校教师开展科研会挤占教学时间，因此科研与教学是对立的。", true, 1, "科研与教学相辅相成：科研为教学提供前沿内容与方法训练，教学为科研提出问题和培养后备力量，二者可以相互促进。"), "");
  put(Q.single("ped-033", "ped-main", "c9", "k3", "高校教师的\"研究者\"角色主要体现为（　　）", ["只传授教材知识", "开展科学研究并以科研反哺教学", "承担全部行政事务", "负责学生日常管理"], "B", 2, "高校教师既是教育者也是研究者，科研反哺教学是其区别于中小学教师的重要角色特征。"), "");
