  put(Q.judge("ped-040", "ped-main", "c1", "k3", "高等教育普及化的标志是毛入学率超过 50%。", true, 1, "按马丁·特罗的划分，毛入学率超过 50% 即进入普及化阶段。"), "");
  put(Q.judge("ped-041", "ped-main", "c11", "k1", "教育信息化就是用多媒体设备上课。", true, 1, "教育信息化是信息技术与教育教学深度融合的系统工程，包括基础设施、数字资源、教学方式变革、治理能力提升等，多媒体设备只是其中一部分。"), "");
