  put(Q.short("ped-s-001", "ped-drill", "c0", "k1", "我国高等教育面临哪些挑战？", "一是国际人才大竞争的挑战；二是高新科技大发展的挑战；三是全球经济大开放的挑战；四是知识经济大崛起的挑战；五是多元文化大汇合的挑战。", ["国际人才", "高新科技", "全球经济", "知识经济", "多元文化"], 10, ""), "《高等教育学试卷（A卷）》");
  put(Q.short("ped-s-002", "ped-drill", "c0", "k2", "简述现代大学的功能。", "现代大学具有教育功能、科研功能、服务功能、产业功能和交流功能：培养专门人才、发展科学技术、直接服务社会、带动相关产业，并开展国际国内学术交流。", ["教育功能", "科研功能", "服务功能", "产业功能", "交流功能"], 10, ""), "《高等教育学试卷（A卷）》");
  put(Q.short("ped-s-003", "ped-drill", "c7", "k1", "新时期高校教师有哪些基本要求？", "一要有正确的政治方向，忠诚于社会主义教育事业；二要热爱学生，遵循学生身心发展规律培养人才；三要具有渊博的知识面，精通所教的专业与学科；四要具有教育教学能力、科研能力与创新能力。", ["政治方向", "热爱学生", "知识面", "教育教学能力", "科研能力", "创新"], 10, ""), "《高等教育学试卷（A卷）》");
  put(Q.short("ped-s-004", "ped-drill", "c10", "k1", "请联系实际，分析教学方法改革的发展趋势。", "一是在功能定位上，由教授知识转向教会学习；二是在指导思想上，推行启发式、废止注入式；三是在结构上，由讲授为主转向指导学生自主学习、独立研究为主；四是要结合学科教学实际灵活运用。", ["教会学习", "启发式", "自主学习", "独立研究"], 10, ""), "《高等教育学试卷（A卷）》");
  put(Q.short("ped-s-005", "ped-drill", "c9", "k1", "试述课程建设的内容和要求。", "内容：教学内容和体系改革、教学设施建设、教学方法与手段改革。要求：教学大纲有特色，教学设施满足要求，教材合适，教学资料完整，考核手段科学。", ["教学内容", "教学设施", "教学方法", "教学大纲", "教材", "考核"], 10, ""), "《2004 年高校教师岗前培训试卷》");
  put(Q.short("ped-s-006", "ped-drill", "c7", "k1", "根据高校教师的地位、作用和任务，试论青年教师应具备的基本素质。", "一是人格素质：爱教之心、爱生之心、爱学之心；二是专业素质：具有先进的教育理念（现代人才观、学生观、终身教育观、素质教育观、教育民主观），全面的文化知识，过硬的教师基本功和较强的教育教学能力。", ["人格素质", "爱教", "爱生", "专业素质", "教育理念", "文化知识"], 10, ""), "《2004 年高校教师岗前培训试卷》");
  put(Q.short("ped-s-007", "ped-drill", "c7", "k1", "请联系实际，试述高校教师素质的具体表现。", "教师素质包括人格素质与专业素质。人格素质表现为爱教之心、爱生之心、爱学之心；专业素质表现为先进的教育理念、全面的文化知识、过硬的教师基本功和较强的教育教学能力。", ["人格素质", "爱教", "爱生", "专业素质", "教育理念", "文化知识"], 10, ""), "《2006 年高校教师岗前培训试卷》");
  put(Q.short("ped-s-008", "ped-drill", "c8", "k1", "结合所任教学科或所学专业，对教学原则体系进行评述。", "高校教学原则体系主要包括：科学性与思想性相统一、传授知识与培养能力相统一、教师主导作用与学生主体作用相结合、面向全体与因材施教相结合、理论与实践相结合；运用时要结合学科特点整体把握。", ["科学性", "思想性", "传授知识", "培养能力", "教师主导", "因材施教", ["理论联系实际", "理论与实践相结合"]], 10, ""), "《2006 年高校教师岗前培训试卷》");
  put(Q.short("ped-n-001", "ped-main", "c0", "k1", "比较高等教育的个体发展价值与社会发展价值。", "个体发展价值体现为拓展知识、发展能力、完善人格和促进职业发展；社会发展价值体现为培养人才、创造知识、服务社会和传承文化。二者相互支持，教育实践应兼顾个人需要与社会需要。", ["个体发展", "社会发展", "知识", "能力", "人格", "文化"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-002", "ped-main", "c9", "k1", "如何把专业培养目标转化为一门课程的学习目标？", "先分析专业培养目标与毕业要求，确定课程支撑的能力；再把能力转化为可观察、可评价的学习表现，明确完成任务的条件与标准；最后使教学活动和考核任务与学习目标一致，并依据评价结果改进。", ["毕业要求", "能力", "学习表现", "评价", "标准"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-003", "ped-main", "c0", "k1", "比较高等教育的内部效率与外部效率，并举出改进思路。", "内部效率关注教育系统内资源投入与人才培养、知识产出之间的关系；外部效率关注教育成果与社会需要的适应程度。改进内部效率可优化课程与资源配置，改进外部效率应加强需求调查、实践教学和毕业生反馈，同时避免只用短期就业指标评价教育。", ["内部效率", "外部效率", "资源", "社会需要", "改进"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-004", "ped-main", "c6", "k1", "高校如何协调行政管理与学术治理？", "明确行政管理与学术治理的职责边界；行政部门做好资源保障和程序服务，学术组织依照制度参与学术标准、学术评价等事务；健全协商、信息公开和监督机制，使管理决策尊重教育规律与学术规律。", ["职责边界", "行政", "学术治理", "制度", "协商"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-005", "ped-main", "c10", "k2", "采用案例教学时，教师应如何组织课堂？", "围绕学习目标选择真实且有讨论空间的案例；课前提供必要材料与问题；课堂引导学生分析证据、比较方案并说明理由；组织小组讨论与全班交流；课后总结理论联系，结合学生表现给予反馈。", ["案例", "问题", "讨论", "分析", "反馈"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-006", "ped-main", "c9", "k1", "如何设计体现知识、能力与价值目标统一的课程？", "先明确知识、能力与价值三类目标；围绕专业真实问题组织课程内容，设计分析、实践和反思任务；将价值讨论融入专业判断，避免脱离学科生硬拼接；使用多元评价检查三类目标的达成，并持续改进。", ["知识", "能力", "价值", "真实问题", "反思"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-007", "ped-main", "c13", "k2", "比较形成性评价与总结性评价在高校课程中的作用。", "形成性评价贯穿学习过程，用于诊断困难、提供反馈和调整教学；总结性评价一般在一个阶段结束时判断学习成果与目标达成程度。两者应结合使用，既关注学习过程，又检验最终成果，并向学生说明评价标准。", ["形成性", "总结性", "反馈", "诊断", "目标"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-008", "ped-main", "c9", "k1", "如何依据学习结果改进一门课程？", "收集作业、考试、课堂表现与学生反馈等证据；按学习目标分析共性困难，区分内容、教学方法和评价设计的问题；提出有针对性的改进措施；在下一轮教学中实施并再次评价，形成持续改进循环。", ["证据", "学习目标", "改进措施", "再次评价"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-009", "ped-main", "c8", "k1", "简述高校教师把科研成果转化为教学资源的途径。", "把适合学生水平的科研问题转化为案例、项目和实验；把研究方法融入课程，指导学生查阅文献、提出问题和分析数据；通过本科生研究等方式提供参与机会；注意知识更新、难度控制及学术诚信教育。", ["案例", "项目", "研究方法", "文献", "本科"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-010", "ped-main", "c6", "k1", "高校开展社会服务时如何兼顾育人与社会需求？", "以学校学科优势对接社会需求，设计具有真实任务的合作项目；把学生学习目标、实践指导和评价要求纳入项目；明确合作各方责任，保障学生权益与安全；评价项目的社会贡献和育人成效，防止单纯追求收入。", ["学科优势", "真实任务", "学习目标", "责任", "育人"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-011", "ped-main", "c7", "k2", "如何指导大学生开展自主学习？", "帮助学生设定具体学习目标并制定计划；提供学习资源和方法示范；引导学生监控理解程度和时间安排；通过反馈与反思调整策略；逐步减少外部支持，培养自我管理能力。", ["目标", "计划", "监控", "反馈", "反思"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("ped-n-012", "ped-main", "c11", "k1", "高校使用数字化教学资源时，应考虑哪些教学设计问题？", "先分析学习者、学习目标与使用情境，再选择适合的数字资源；设计促进思考和互动的学习任务；兼顾资源可获得性与无障碍需求；重视个人信息保护和版权；依据学习反馈评价效果，避免以技术数量代替教学质量。", ["学习者", "学习目标", "任务", "互动", "无障碍"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
