  put(Q.single("ped-sup-009", "ped-main", "c4", "k3", "按教育层次划分，高等教育分为专科教育、本科教育和（　　）", ["研究生教育", "职业教育", "成人教育", "继续教育"], "A", 2, "高等教育层次结构由专科、本科、研究生教育构成。"), "教材目录自编");
