  put(Q.multiple("ped-sup-026", "ped-drill", "c11", "k3", "人工智能在高等教育中的应用包括（　　）", ["智能辅导", "自动批改", "学习分析", "个性化推荐"], ["A", "B", "C", "D"], 3, "智能辅导、自动批改、学习分析、个性化推荐都是常见应用。"), "教材目录自编");
